esc=lambda t:t.replace('\\','\\\\').replace(',','\\,').replace(';','\\;')
now=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
L=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//Zip//Craig Trips//EN","CALSCALE:GREGORIAN","METHOD:PUBLISH","X-WR-CALNAME:Craig Trips","REFRESH-INTERVAL;VALUE=DURATION:PT1H","X-PUBLISHED-TTL:PT1H"]
for u,s,a,at,b,bt,l,d in EVENTS:
  L+=["BEGIN:VEVENT",f"UID:{u}@craig-trips",f"DTSTAMP:{now}",f"LAST-MODIFIED:{now}",f"DTSTART:{U(a,at)}",f"DTEND:{U(b,bt)}",f"SUMMARY:{esc(s)}",f"LOCATION:{esc(l)}",f"DESCRIPTION:{esc(d)}","BEGIN:VALARM","ACTION:DISPLAY",f"DESCRIPTION:{esc(s)}","TRIGGER:-PT3H","END:VALARM","END:VEVENT"]
for u,s,a,b,l,d in STAYS:
  L+=["BEGIN:VEVENT",f"UID:{u}@craig-trips",f"DTSTAMP:{now}",f"DTSTART;VALUE=DATE:{a}",f"DTEND;VALUE=DATE:{b}",f"SUMMARY:{esc(s)}",f"LOCATION:{esc(l)}",f"DESCRIPTION:{esc(d)}","TRANSP:TRANSPARENT","END:VEVENT"]
L.append("END:VCALENDAR")
def fold(x):
  o=[];
  while len(x.encode())>75: o.append(x[:74]); x=' '+x[74:]
  return "\r\n".join(o+[x])
open('trips.ics','w',newline='').write("\r\n".join(map(fold,L))+"\r\n")
